<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_permission('BITACORA_VER');$q=trim((string)($_GET['q']??''));$action=trim((string)($_GET['accion']??''));$limit=max(20,min(500,(int)($_GET['limit']??200)));$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$where=['1=1'];if($q!==''){$esc=$db->real_escape_string($q);$where[]="(b.descripcion LIKE '%$esc%' OR b.entidad LIKE '%$esc%' OR b.entidad_id LIKE '%$esc%' OR u.username LIKE '%$esc%')";}if($action!==''){$esc=$db->real_escape_string($action);$where[]="b.accion='$esc'";}$sql="SELECT b.bitacora_id,b.accion,b.entidad,b.entidad_id,b.descripcion,b.ip,b.created_at,u.username,CONCAT_WS(' ',u.nombre,u.apellido_paterno,u.apellido_materno) usuario FROM bitacora b LEFT JOIN usuario u ON u.usuario_id=b.usuario_id WHERE ".implode(' AND ',$where)." ORDER BY b.created_at DESC,b.bitacora_id DESC LIMIT $limit";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){$r['bitacora_id']=(int)$r['bitacora_id'];$data[]=$r;}$db->close();json_response(['ok'=>true,'data'=>$data]);
